"""Recursive-descent parser for the contract grammar (EBNF and precedence table)."""
from __future__ import annotations

from .errors import ParseError
from .lexer import Token, tokenize
from .nodes import (
    Binary, Call, ColumnRef, ExprItem, InList, IsNull, Join, Like, Literal, Logical, Not,
    OrderItem, Paren, QualifiedStarItem, Query, StarItem, TableRef, Unary,
)

_CMP_OPS = ("=", "<>", "!=", "<", "<=", ">", ">=")
_NAME_KINDS = ("IDENT", "QIDENT")
_LITERAL_KINDS = {"INTEGER": "INTEGER", "REAL": "REAL", "STRING": "TEXT"}


def parse(sql: str) -> Query:
    return _Parser(sql, tokenize(sql)).query()


class _Parser:
    def __init__(self, sql, tokens):
        self.sql = sql
        self.tokens = tokens
        self.i = 0
        self.last_end = 0

    # ---- token helpers ----

    def peek(self, k=0) -> Token:
        return self.tokens[min(self.i + k, len(self.tokens) - 1)]

    def advance(self) -> Token:
        tok = self.tokens[self.i]
        self.i += 1
        self.last_end = tok.end
        return tok

    def is_kw(self, word, k=0):
        tok = self.peek(k)
        return tok.kind == "KEYWORD" and tok.value == word

    def is_op(self, op, k=0):
        tok = self.peek(k)
        return tok.kind == "OP" and tok.value == op

    def accept_kw(self, word):
        return self.advance() if self.is_kw(word) else None

    def accept_op(self, op):
        return self.advance() if self.is_op(op) else None

    def error(self):
        tok = self.peek()
        if tok.kind == "EOF":
            return ParseError.at(self.sql, len(self.sql), "unexpected end of input")
        return ParseError.at(self.sql, tok.start, "unexpected token '%s'" % tok.text)

    def expect_kw(self, word):
        tok = self.accept_kw(word)
        if tok is None:
            raise self.error()
        return tok

    def expect_op(self, op):
        tok = self.accept_op(op)
        if tok is None:
            raise self.error()
        return tok

    def expect_name(self):
        if self.peek().kind not in _NAME_KINDS:
            raise self.error()
        return self.advance()

    def comma_list(self, parse_one):
        items = [parse_one()]
        while self.accept_op(","):
            items.append(parse_one())
        return items

    # ---- clauses ----

    def query(self):
        select = self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT") is not None
        items = self.comma_list(self.item)
        from_table, joins = None, []
        if self.accept_kw("FROM"):
            from_table = self.tableref()
            while True:
                join = self.join()
                if join is None:
                    break
                joins.append(join)
        where = self.expr() if self.accept_kw("WHERE") else None
        group_by = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by = self.comma_list(self.expr)
        having = self.expr() if self.accept_kw("HAVING") else None
        order_by = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by = self.comma_list(self.order)
        limit = self.integer() if self.accept_kw("LIMIT") else None
        offset = self.integer() if self.accept_kw("OFFSET") else None
        self.accept_op(";")
        if self.peek().kind != "EOF":
            raise self.error()
        return Query(distinct, items, from_table, joins, where, group_by, having, order_by,
                     limit, offset, select.start, self.last_end, select.start)

    def integer(self):
        if self.peek().kind != "INTEGER":
            raise self.error()
        return self.advance().value

    def item(self):
        tok = self.peek()
        if self.is_op("*"):
            self.advance()
            return StarItem(tok.start, tok.end, tok.start)
        if tok.kind in _NAME_KINDS and self.is_op(".", 1) and self.is_op("*", 2):
            self.advance()
            self.advance()
            star = self.advance()
            return QualifiedStarItem(tok.value, tok.start, star.start, tok.start, star.end, tok.start)
        expr = self.expr()
        alias, alias_pos = self.alias()
        return ExprItem(expr, alias, alias_pos, expr.start, expr.end, expr.start)

    def alias(self):
        if self.accept_kw("AS") or self.peek().kind in _NAME_KINDS:
            tok = self.expect_name()
            return tok.value, tok.start
        return None, None

    def tableref(self):
        name = self.expect_name()
        alias, alias_pos = self.alias()
        return TableRef(name.value, name.start, alias, alias_pos, name.start, self.last_end, name.start)

    def join(self):
        first = self.peek()
        if self.accept_kw("INNER"):
            self.expect_kw("JOIN")
            kind = "INNER"
        elif self.accept_kw("JOIN"):
            kind = "INNER"
        elif self.accept_kw("LEFT"):
            self.accept_kw("OUTER")
            self.expect_kw("JOIN")
            kind = "LEFT"
        else:
            return None
        table = self.tableref()
        self.expect_kw("ON")
        on = self.expr()
        return Join(kind, table, on, first.start, on.end, first.start)

    def order(self):
        expr = self.expr()
        desc = False
        if self.accept_kw("DESC"):
            desc = True
        else:
            self.accept_kw("ASC")
        return OrderItem(expr, desc, expr.start, self.last_end, expr.start)

    # ---- expressions ----

    def expr(self):
        return self.logical("OR", self.and_expr)

    def and_expr(self):
        return self.logical("AND", self.not_expr)

    def logical(self, word, operand):
        left = operand()
        while self.is_kw(word):
            op = self.advance()
            right = operand()
            left = Logical(word, left, right, left.start, right.end, op.start)
        return left

    def not_expr(self):
        tok = self.accept_kw("NOT")
        if tok is None:
            return self.cmp()
        operand = self.not_expr()
        return Not(operand, tok.start, operand.end, tok.start)

    def cmp(self):
        left = self.add()
        tok = self.peek()
        if tok.kind == "OP" and tok.value in _CMP_OPS:
            self.advance()
            right = self.add()
            return Binary(tok.value, left, right, left.start, right.end, tok.start)
        if self.accept_kw("IS"):
            negated = self.accept_kw("NOT") is not None
            self.expect_kw("NULL")
            return IsNull(left, negated, left.start, self.last_end, tok.start)
        negated = self.accept_kw("NOT") is not None
        kw = self.accept_kw("LIKE")
        if kw is not None:
            pattern = self.add()
            escape = None
            if self.accept_kw("ESCAPE"):
                if self.peek().kind != "STRING":
                    raise self.error()
                esc = self.advance()
                escape = Literal("TEXT", esc.value, esc.start, esc.end, esc.start)
            return Like(left, pattern, escape, negated, escape and escape.pos,
                        left.start, self.last_end, kw.start)
        kw = self.accept_kw("IN")
        if kw is not None:
            self.expect_op("(")
            items = self.comma_list(self.expr)
            self.expect_op(")")
            return InList(left, items, negated, left.start, self.last_end, kw.start)
        if negated:  # NOT after an operand must introduce NOT LIKE / NOT IN
            raise self.error()
        return left

    def add(self):
        return self.binary(("+", "-"), self.mul)

    def mul(self):
        return self.binary(("*", "/", "%"), self.unary)

    def binary(self, ops, operand):
        left = operand()
        while self.peek().kind == "OP" and self.peek().value in ops:
            op = self.advance()
            right = operand()
            left = Binary(op.value, left, right, left.start, right.end, op.start)
        return left

    def unary(self):
        tok = self.peek()
        if self.is_op("-") or self.is_op("+"):
            self.advance()
            operand = self.unary()
            return Unary(tok.value, operand, tok.start, operand.end, tok.start)
        return self.primary()

    def primary(self):
        tok = self.peek()
        if tok.kind in _LITERAL_KINDS:
            self.advance()
            return Literal(_LITERAL_KINDS[tok.kind], tok.value, tok.start, tok.end, tok.start)
        if self.is_kw("NULL"):
            self.advance()
            return Literal("NULL", None, tok.start, tok.end, tok.start)
        if self.is_op("("):
            self.advance()
            inner = self.expr()
            close = self.expect_op(")")
            return Paren(inner, tok.start, close.end, tok.start)
        if tok.kind not in _NAME_KINDS:
            raise self.error()
        self.advance()
        if self.is_op("("):
            self.advance()
            arg, star, star_pos = None, False, None
            if self.is_op("*"):
                star, star_pos = True, self.advance().start
            else:
                arg = self.expr()
            close = self.expect_op(")")
            return Call(tok.value, arg, star, star_pos, tok.start, close.end, tok.start)
        if self.accept_op("."):
            name = self.expect_name()
            return ColumnRef(tok.value, name.value, tok.start, name.start, tok.start, name.end, tok.start)
        return ColumnRef(None, tok.value, None, tok.start, tok.start, tok.end, tok.start)

